using System;
using System.Linq;
using System.Reflection;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.UI;
namespace CatCafePreview.Editor
{
    public static class PythonStartFlowVerification
    {
        static void Check(bool value,string message){if(!value)throw new Exception(message);}
        static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
        public static void BuildAndVerify()
        {
            PythonStartFlowLayout.Build();EditorSceneManager.OpenScene("Assets/Scenes/CatCafeTitle.unity");var title=UnityEngine.Object.FindObjectOfType<PythonTitleScreen>();var state=PythonServiceSetup.Sample();state.instance_id="start-flow";state.new_game_options=new[]{"popularity","patron","bond","free"}.Select(id=>new PythonNewGameOption{choice=id,label=id=="popularity"?"人気3段階":id=="patron"?"有力者への派遣":id=="bond"?"猫たちとの好感度":"自由営業",detail="目標の説明："+id,conditions="初期猫5匹 / 席2席 / 資金1000"}).ToArray();title.Apply(state);title.ApplySaves(new PythonSaveList{saves=new PythonSavedGame[0]});title.ShowConditions();
            for(int i=0;i<4;i++){title.objectives.value=i;title.SelectObjective(i);Check(title.conditions.text.Contains(state.new_game_options[i].label) && title.conditions.text.Contains("1000"),"Start rules missing");title.StartNewGame();Check(title.ConfirmingStart && !(bool)typeof(PythonTitleScreen).GetField("busy",Flags).GetValue(title),"First click sent start");title.Apply(state);Check(title.ConfirmingStart,"Unchanged polling cancelled start");title.conditionsBack.onClick.Invoke();Check(!title.ConfirmingStart && title.conditionsPanel.activeSelf,"Cancel left conditions");}
            title.StartNewGame();state.revision++;title.Apply(state);Check(!title.ConfirmingStart,"Updated state retained start confirmation");title.StartNewGame();title.SelectObjective(0);Check(!title.ConfirmingStart,"Selection retained confirmation");title.StartNewGame();title.Disconnect("未接続");Check(!title.ConfirmingStart && !title.startGame.interactable,"Offline start enabled");title.Apply(state);title.ShowConditions();state.new_game_options[0].conditions=string.Join("\n",Enumerable.Repeat("開始条件を詳しく確認するための長い説明です。",35));title.Apply(state);title.objectives.SetValueWithoutNotify(0);title.SelectObjective(0);Canvas.ForceUpdateCanvases();var scroll=title.conditions.GetComponentInParent<ScrollRect>();Check(scroll.content.rect.height>scroll.viewport.rect.height,"Long start conditions clipped");title.StartNewGame();CaptureTitle("StartFlowConditions");title.ShowHome();Check(!title.ConfirmingStart && title.home.activeSelf,"Home retained confirmation");
            var browser=title.GetComponent<PythonSaveBrowser>();browser.OpenLoad();Check(!browser.action.interactable,"Empty slot enabled load");title.ApplySaves(new PythonSaveList{saves=new[]{new PythonSavedGame{slot=1,save_id="ended-record",label="5日目 / 経営終了",phase="ended",created_at="2026-10-10T00:00:00+09:00"}}});browser.cards[0].onClick.Invoke();browser.Choose();Check(browser.confirmation.activeSelf && browser.confirmationText.text.Contains("経営終了"),"Ended save review missing");title.ShowHome();Check(!browser.confirmation.activeSelf && !browser.panel.activeSelf,"Home retained load confirmation");title.ShowConditions();state.instance_id="replacement";title.Apply(state);Check(title.home.activeSelf && !title.conditionsPanel.activeSelf,"New instance retained start page");title.ShowHome();CaptureTitle("StartFlowHome");state.new_game_options=new PythonNewGameOption[0];title.Apply(state);title.ShowConditions();Check(!title.startGame.interactable && title.conditions.text.Contains("取得していません"),"Missing options retained old rules");
            EditorSceneManager.OpenScene("Assets/Scenes/CatCafePythonState.unity");var preview=UnityEngine.Object.FindObjectOfType<ContentPreview>();preview.Initialize();var client=preview.GetComponent<PythonStateClient>();typeof(PythonStateClient).GetField("preview",Flags).SetValue(client,preview);state=PythonServiceSetup.Sample();state.instance_id="end-flow";state.can_set_shifts=false;state.game_over=new PythonGameOver{reason="funds",day=5,popularity=10};state.funds=0;Action apply=()=>typeof(PythonStateClient).GetMethod("Accept",Flags).Invoke(client,new object[]{state});apply();preview.GetComponent<PythonPreparationPanel>().Close();var result=preview.GetComponent<PythonGameOverPanel>();browser=preview.GetComponent<PythonSaveBrowser>();preview.GetComponent<PythonSavePanel>().Apply(new PythonSaveList{saves=new PythonSavedGame[0]});Check(result.summary.text.Contains("資金不足") && result.notice.text.Contains("はじめから"),"End summary and navigation missing");Canvas.ForceUpdateCanvases();Check(result.notice.preferredHeight<=result.notice.rectTransform.rect.height+1,"End navigation clipped");Check(result.details.text.Contains("猫たちの状態"),"Cat heading missing");CaptureBusiness(preview,"StartFlowResult");result.save.onClick.Invoke();Check(browser.panel.activeSelf && typeof(PythonStateClient).GetField("pending",Flags).GetValue(client)==null,"Save bypassed slot choice");apply();Check(browser.panel.transform.GetSiblingIndex()>result.panel.transform.GetSiblingIndex(),"Polling covered save browser");browser.cards[0].onClick.Invoke();browser.Choose();Check(browser.confirmation.activeSelf,"End save confirmation missing");browser.CancelAndRefresh();browser.Close();Check(result.panel.activeSelf,"Save close hid end result");result.Disconnect();Check(!result.save.interactable,"Offline end save enabled");apply();Check(result.save.interactable,"Reconnected end save disabled");
            result.save.onClick.Invoke();browser.cards[0].onClick.Invoke();browser.Choose();browser.Confirm();var command=(PythonShiftCommand)typeof(PythonStateClient).GetField("pending",Flags).GetValue(client);Check(command!=null && command.kind=="save_game" && command.save_slot==1,"End save slot command wrong");browser.Confirm();Check(ReferenceEquals(command,typeof(PythonStateClient).GetField("pending",Flags).GetValue(client)),"Duplicate save queued");typeof(PythonStateClient).GetField("pending",Flags).SetValue(client,null);browser.Close();state.instance_id="new-cafe";state.game_over=null;state.can_set_shifts=true;state.revision++;apply();Check(!result.panel.activeSelf && !browser.confirmation.activeSelf,"New game retained result");Debug.Log("CAT_CAFE_START_FLOW_OK: four modes / confirmation / cancel / polling / revision / offline / long conditions / ended load / home / instance reset / result / save slot / save focus / duplicate");
        }
        static void CaptureTitle(string name){typeof(PythonTitleSetup).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{"Logs/"+name+".png"});}
        static void CaptureBusiness(ContentPreview preview,string name){Canvas.ForceUpdateCanvases();typeof(ContentPreviewSetup).GetMethod("CaptureCanvas",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{preview,"Logs/"+name+".png"});}
    }
}
